-- Origin SQL:
SELECT * FROM a INTERSECT SELECT * FROM b;
SELECT 1 INTERSECT DISTINCT SELECT 1;
SELECT 1 INTERSECT ALL SELECT 1;
SELECT 1 EXCEPT DISTINCT SELECT 2;
SELECT 1 EXCEPT ALL SELECT 2;
SELECT 1 UNION SELECT 2;
SELECT 1 UNION ALL SELECT 2 INTERSECT SELECT 3 EXCEPT SELECT 4;
(SELECT 1) INTERSECT (SELECT 1);
SELECT * FROM (SELECT a FROM t INTERSECT SELECT a FROM u) WHERE a > 1;
WITH x AS (SELECT 1 INTERSECT SELECT 1) SELECT * FROM x;
SELECT 1 AS intersect;
SELECT * FROM t AS intersect;
SELECT 1 EXCEPT SELECT 2;
SELECT 1 EXCEPT (SELECT 2);
SELECT * EXCEPT (a) FROM t EXCEPT SELECT * FROM u;


